"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/file-manager/variants/01-workspace";
export interface ArtemisFileManagerProps { className?: string;  }
export function ArtemisFileManager({className}:ArtemisFileManagerProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { useArtemisFileDrag } from "../../../lib/file-drag";
import { DialogTitle, Description, Listbox, ListboxButton, ListboxOption, ListboxOptions } from "../../../lib/headless";
import { Check, ChevronDown, ChevronRight, Download, Ellipsis, File as FileIcon, FileSpreadsheet, FileText, Folder, FolderPlus, Grid2x2, HardDrive, List, Pencil, Search, Star, Trash2, Upload, X, } from "lucide-react";
import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { type ChangeEvent, type DragEvent, type FormEvent, type KeyboardEvent, forwardRef, useId, useMemo, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { ActionMenu, type MenuAction } from "./01-workspace/action-menu";
import { type Entry, type SortKey, type TabKey, SORT_OPTIONS, descendants, fileIconKind, folderChain, formatSize, isTextFile, itemCountLabel, matchesQuery, previewText, seedEntries, sortEntries, uniqueName, validateName, } from "./01-workspace/data";
import { WorkspaceModal } from "./01-workspace/modal";
const UNDERLINE_TRANSITION = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 } as const;
const CARD_TRANSITION = { duration: 0.18, ease: ARTEMIS_EASE_OUT } as const;
const PressButton = forwardRef<HTMLButtonElement, HTMLMotionProps<"button">>(function PressButton({ type = "button", tabIndex = 0, ...props }, ref) {
    const reduce = useReducedMotion();
    return (<motion.button ref={ref} type={type} tabIndex={tabIndex} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} {...props}/>);
});
const GHOST_TEXT = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full";
const PRIMARY = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full";
const CLOSE_BUTTON = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:shrink-0 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full";
const TRIGGER_BASE = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:text-foreground art:focus-visible:outline-none art:hover:bg-muted art:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:size-9 art:shrink-0 art:focus-visible:ring-2 art:focus-visible:ring-ring";
const OPEN_OVERLAY = "art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-ring art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:inset-0 art:size-full art:cursor-pointer art:outline-none art:focus-visible:ring-0 art:focus-visible:ring-offset-0 art:rounded-full";
const TAB_ACTIVE = "art:relative art:isolate art:-mb-px art:inline-flex art:items-center art:px-3 art:pt-1 art:pb-2.5 art:font-medium art:text-sm art:transition-colors art:text-foreground art:h-9 art:min-h-9 art:rounded-full art:focus-visible:ring-2 art:focus-visible:ring-ring";
const TAB_IDLE = "art:relative art:isolate art:-mb-px art:inline-flex art:items-center art:px-3 art:pt-1 art:pb-2.5 art:font-medium art:text-sm art:transition-colors art:text-muted-foreground art:hover:text-foreground art:h-9 art:min-h-9 art:rounded-full art:focus-visible:ring-2 art:focus-visible:ring-ring";
const VIEW_BUTTON = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:focus-visible:ring-2 art:focus-visible:ring-ring";
const VIEW_BUTTON_IDLE = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full";
const TABS: ReadonlyArray<{
    key: TabKey;
    label: string;
}> = [
    { key: "files", label: "All files" },
    { key: "starred", label: "Starred" },
    { key: "recent", label: "Recent" },
];
type Layout = "grid" | "list";
type DialogState = {
    kind: "create";
} | {
    kind: "rename";
    id: string;
} | {
    kind: "preview";
    id: string;
} | null;
export default function FileManagerWorkspace() {
const artemisInstanceId = useArtemisInstanceId();

    const reduce = useReducedMotion();
    const baseId = useId();
    const tabsId = `${baseId}-tabs`;
    const [entries, setEntries] = useState<Entry[]>(seedEntries);
    const [tab, setTab] = useState<TabKey>("files");
    const [folderId, setFolderId] = useState<string | null>(null);
    const [query, setQuery] = useState("");
    const [searchFocused, setSearchFocused] = useState(false);
    const { dragging, events: dragEvents, reset: clearDrag } = useArtemisFileDrag();
    const [layout, setLayout] = useState<Layout>("grid");
    const [sort, setSort] = useState<SortKey>("name");
    const [message, setMessage] = useState("");
    const [undo, setUndo] = useState<Entry[] | null>(null);
    const [dialog, setDialog] = useState<DialogState>(null);
    const [lastDialog, setLastDialog] = useState<Exclude<DialogState, null>>({ kind: "create" });
    const [draft, setDraft] = useState("");
    const [error, setError] = useState("");
    const [nameFocused, setNameFocused] = useState(false);
    const fileInput = useRef<HTMLInputElement>(null);
    const searchInput = useRef<HTMLInputElement>(null);
    const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
    const clock = useRef(100);
    const tick = () => {
        clock.current += 1;
        return clock.current;
    };
    const files = entries.filter((e) => e.kind === "file");
    const totalBytes = files.reduce((sum, e) => sum + (e.size ?? 0), 0);
    const effectiveSort: SortKey = tab === "recent" ? "modified" : sort;
    const visible = useMemo(() => {
        let pool: Entry[];
        if (tab === "files")
            pool = entries.filter((e) => e.parentId === folderId);
        else if (tab === "starred")
            pool = entries.filter((e) => e.starred);
        else
            pool = entries.filter((e) => e.kind === "file");
        pool = pool.filter((e) => matchesQuery(e, query));
        const sorted = sortEntries(pool, effectiveSort);
        return {
            folders: sorted.filter((e) => e.kind === "folder"),
            files: sorted.filter((e) => e.kind === "file"),
        };
    }, [entries, tab, folderId, query, effectiveSort]);
    const chain = tab === "files" ? folderChain(entries, folderId) : [];
    const say = (text: string, restore: Entry[] | null = null) => {
        setMessage(text);
        setUndo(restore);
    };
    const openDialog = (next: Exclude<DialogState, null>) => {
        setNameFocused(false);
        setLastDialog(next);
        setDialog(next);
    };
    const openCreate = () => {
        setDraft("");
        setError("");
        openDialog({ kind: "create" });
    };
    const openRename = (entry: Entry) => {
        setDraft(entry.name);
        setError("");
        openDialog({ kind: "rename", id: entry.id });
    };
    const openEntry = (entry: Entry) => {
        if (entry.kind === "folder") {
            setTab("files");
            setFolderId(entry.id);
            setQuery("");
            return;
        }
        openDialog({ kind: "preview", id: entry.id });
    };
    const toggleStar = (entry: Entry) => {
        setEntries((list) => list.map((e) => (e.id === entry.id ? { ...e, starred: !e.starred } : e)));
    };
    const remove = (entry: Entry) => {
        const nested = entry.kind === "folder" ? descendants(entries, entry.id) : [];
        const gone = new Set([entry.id, ...nested.map((e) => e.id)]);
        const removed = entries.filter((e) => gone.has(e.id));
        setEntries((list) => list.filter((e) => !gone.has(e.id)));
        say(`${entry.name} deleted ${nested.length ? `with ${nested.length} nested items` : ""}.`, removed);
    };
    const restore = () => {
        if (!undo)
            return;
        const back = undo;
        setEntries((list) => [...list, ...back.filter((e) => !list.some((x) => x.id === e.id))]);
        say("Deleted items restored.");
    };
    const submitName = (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        if (!dialog || dialog.kind === "preview")
            return;
        const target = dialog.kind === "rename" ? entries.find((e) => e.id === dialog.id) : undefined;
        const parentId = target ? target.parentId : folderId;
        const problem = validateName(entries, draft, parentId, target?.id);
        if (problem) {
            setError(problem);
            return;
        }
        const name = draft.trim();
        if (target) {
            setEntries((list) => list.map((e) => (e.id === target.id ? { ...e, name, modified: tick() } : e)));
            say("Name updated.");
        }
        else {
            const id = `folder-${tick()}`;
            setEntries((list) => [...list, { id, kind: "folder", name, parentId, starred: false, modified: clock.current }]);
            say("Folder created.");
        }
        setDialog(null);
    };
    const onUpload = (event: ChangeEvent<HTMLInputElement>) => {
        const input = event.currentTarget;
        const picked = Array.from(input.files ?? []);
        input.value = "";
        void addFiles(picked);
    };
    const onDrop = (event: DragEvent<HTMLDivElement>) => {
        if (!event.dataTransfer.types.includes("Files"))
            return;
        event.preventDefault();
        clearDrag();
        void addFiles(Array.from(event.dataTransfer.files));
    };
    const addFiles = async (picked: File[]) => {
        const parentId = folderId;
        const accepted = picked.slice(0, 20).filter((file) => file.size <= 25 * 1024 * 1024);
        const skipped = picked.length - accepted.length;
        const added = await Promise.all(accepted.map(async (file) => {
            const text = isTextFile(file.name, file.type) ? await file.text() : undefined;
            const url = file.type.startsWith("image/") ? URL.createObjectURL(file) : undefined;
            return { file, text, url };
        }));
        const modified = tick();
        setEntries((list) => {
            const taken = new Set(list.filter((e) => e.parentId === parentId).map((e) => e.name.toLowerCase()));
            const next = [...list];
            for (const { file, text, url } of added) {
                const name = uniqueName(taken, file.name);
                taken.add(name.toLowerCase());
                const stamp = tick();
                next.push({
                    id: `upload-${stamp}`,
                    kind: "file",
                    name,
                    parentId,
                    starred: false,
                    modified,
                    content: text,
                    size: file.size,
                    blob: file,
                    url,
                    mime: file.type,
                });
            }
            return next;
        });
        setTab("files");
        setQuery("");
        say(`${accepted.length} ${accepted.length === 1 ? "file" : "files"} added locally. ${skipped ? `${skipped} skipped; limit 20 files, 25 MB each.` : ""}`);
    };
    const download = (entry: Entry) => {
        const href = entry.url ?? URL.createObjectURL(entry.blob ?? new Blob([entry.content ?? ""], { type: entry.mime || "text/plain" }));
        const a = document.createElement("a");
        a.href = href;
        a.download = entry.name;
        a.click();
        if (!entry.url)
            window.setTimeout(() => URL.revokeObjectURL(href), 0);
    };
    const selectTab = (key: TabKey) => {
        setTab(key);
        setQuery("");
    };
    const onTabKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
        let next = -1;
        if (event.key === "ArrowRight")
            next = (index + 1) % TABS.length;
        else if (event.key === "ArrowLeft")
            next = (index - 1 + TABS.length) % TABS.length;
        else if (event.key === "Home")
            next = 0;
        else if (event.key === "End")
            next = TABS.length - 1;
        if (next < 0)
            return;
        event.preventDefault();
        const nextTab = TABS[next];
        if (!nextTab)
            return;
        selectTab(nextTab.key);
        tabRefs.current[next]?.focus();
    };
    const menuFor = (entry: Entry): MenuAction[] => [
        {
            id: "open",
            label: entry.kind === "folder" ? "Open folder" : "Open preview",
            onSelect: () => openEntry(entry),
        },
        {
            id: "star",
            label: entry.starred ? "Unstar" : "Add to starred",
            icon: <Star className="art:size-4"/>,
            onSelect: () => toggleStar(entry),
        },
        { id: "rename", label: "Rename", icon: <Pencil className="art:size-4"/>, onSelect: () => openRename(entry) },
        {
            id: "delete",
            label: "Delete",
            destructive: true,
            icon: <Trash2 className="art:size-4"/>,
            onSelect: () => remove(entry),
        },
    ];
    const active = dialog ?? lastDialog;
    const activeEntry = active.kind === "create" ? undefined : entries.find((e) => e.id === active.id);
    const searching = query.trim().length > 0;
    const empty = visible.folders.length === 0 && visible.files.length === 0;
    const list = layout === "list";
    const renderEntry = (entry: Entry) => {
        const isFolder = entry.kind === "folder";
        const kind = fileIconKind(entry);
        const meta = isFolder ? itemCountLabel(entries.filter((e) => e.parentId === entry.id).length) : formatSize(entry.size ?? 0);
        const FileGlyph = kind === "spreadsheet" ? FileSpreadsheet : kind === "file" || kind === "image" ? FileIcon : FileText;
        return (<motion.div key={entry.id} initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} transition={reduce ? { duration: 0 } : CARD_TRANSITION}>
        <article className={list
                ? "art:relative art:min-w-0 art:flex art:items-center art:gap-3 art:border-b art:border-border/60 art:py-3" : "art:relative art:min-w-0 art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-4"}>
          <div className={list
                ? "art:relative art:min-w-0 art:text-left art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-ring art:flex art:flex-1 art:items-center art:gap-3 art:rounded-full" : "art:relative art:min-w-0 art:text-left art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-ring art:block art:w-full art:rounded-xl"}>
            {isFolder || list ? (<span className={list ? "art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-full art:bg-muted" : "art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-full art:bg-muted art:mb-4"}>
                {isFolder ? <Folder className="art:size-5"/> : <FileGlyph className="art:size-5"/>}
              </span>) : (<div className="art:mb-4 art:flex art:h-32 art:items-center art:justify-center art:overflow-hidden art:rounded-xl art:bg-muted/50">
                {entry.url ? (<img alt="" className="art:size-full art:object-cover" src={entry.url}/>) : entry.content !== undefined ? (<div aria-hidden="true" className="art:h-24 art:w-4/5 art:overflow-hidden art:rounded-lg art:bg-background art:p-3 art:text-xs art:leading-5 art:text-muted-foreground">
                    <span className="art:mb-2 art:block art:h-1 art:w-8 art:rounded-full art:bg-accent/40"/>
                    <p className="art:whitespace-pre-wrap">{previewText(entry)}</p>
                  </div>) : (<span className="art:flex art:size-12 art:items-center art:justify-center art:rounded-full art:bg-background">
                    <FileIcon className="art:size-5"/>
                  </span>)}
              </div>)}
            <div className={list ? "art:min-w-0" : "art:min-w-0 art:pr-8"}>
              <h3 title={entry.name} className="art:truncate art:text-xl art:font-medium">
                {entry.name}
              </h3>
              <p className="art:mt-1 art:text-xs art:text-muted-foreground">{meta}</p>
            </div>
            <button type="button" className={OPEN_OVERLAY} aria-label={`Open ${entry.name}`} onClick={() => openEntry(entry)}/>
          </div>
          {entry.starred ? (<Star className={list
                    ? "art:size-3.5 art:shrink-0 art:fill-current art:text-muted-foreground" : "art:size-3.5 art:shrink-0 art:fill-current art:text-muted-foreground art:absolute art:right-5 art:top-5"} aria-label="Starred"/>) : null}
          <ActionMenu label={`Actions for ${entry.name}`} actions={menuFor(entry)} className={list ? `${TRIGGER_BASE} art:h-9 art:rounded-full` : `${TRIGGER_BASE} art:absolute art:bottom-3 art:right-2 art:h-9 art:rounded-full`} icon={<Ellipsis className="art:size-4"/>}/>
        </article>
      </motion.div>);
    };
    const renderSection = (label: string, items: Entry[]) => items.length ? (<section aria-label={label}>
        <h3 className="art:mb-4 art:text-muted-foreground art:text-xl art:font-medium">{label}</h3>
        <div className={list ? "art:space-y-1" : "art:grid art:gap-4 art:@min-[640px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:grid-cols-4"}>{items.map(renderEntry)}</div>
      </section>) : null;
    const formDialog = active.kind === "create" || active.kind === "rename";
    const fieldState = nameFocused ? "focused" : "idle";
    return (<>
      <section className="art:w-full art:text-foreground">
        <div className="art:mx-auto art:max-w-6xl">
          <header className="art:flex art:flex-wrap art:items-start art:justify-between art:gap-5">
            <div>
              <p className="art:text-sm art:text-muted-foreground">{"Your workspace, organized"}</p>
              <h2 className="art:mt-3 art:tracking-tight art:text-xl art:font-medium">{"Files"}</h2>
              <p className="art:mt-3 art:text-sm art:text-muted-foreground">{"A home for the work you want to keep close."}</p>
            </div>
            <div className="art:flex art:gap-2">
              <PressButton className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" onClick={openCreate}>
                <FolderPlus className="art:size-4"/>
                {"New folder"}
              </PressButton>
              <PressButton className={PRIMARY} onClick={() => fileInput.current?.click()}>
                <Upload className="art:size-4"/>
                {"Upload files"}
              </PressButton>
            </div>
          </header>
          <input ref={fileInput} type="file" multiple aria-label="Upload files" className="art:hidden" onChange={onUpload}/>
          <div className="art:mt-8 art:flex art:flex-wrap art:items-center art:justify-between art:gap-4">
            <div>
              <div role="tablist" className="art:inline-flex art:items-center art:border-b art:border-border art:gap-4" aria-label="File views">
                {TABS.map((t, index) => {
            const selected = tab === t.key;
            return (<button key={t.key} ref={(node) => {
                    tabRefs.current[index] = node;
                }} type="button" role="tab" aria-selected={selected} className={selected ? TAB_ACTIVE : TAB_IDLE} id={`${tabsId}-${t.key}`} aria-controls={`${tabsId}-content`} tabIndex={selected ? 0 : -1} onClick={() => selectTab(t.key)} onKeyDown={(event) => onTabKeyDown(event, index)}>
                      {t.label}
                      {selected ? (<motion.span layoutId={`${tabsId}-underline`} layout="position" className="art:absolute art:right-0 art:-bottom-px art:left-0 art:h-px art:bg-primary" transition={reduce ? { duration: 0 } : UNDERLINE_TRANSITION}/>) : null}
                    </button>);
        })}
              </div>
            </div>
            <div className="art:flex art:items-center art:gap-2">
              <div className="art:flex art:flex-col art:gap-1.5 art:w-48 art:@min-[640px]/artemis:w-56">
                <div data-state={searchFocused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${searchFocused ? "art:border-muted-foreground/40" : "art:border-border"}`}>
                  <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
                    <Search className="art:size-4"/>
                  </span>
                  <input ref={searchInput} id={`${baseId}-search`} aria-label="Search files" placeholder="Search files…" className="art:peer art:h-full art:w-full art:bg-transparent art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:pl-9 art:pr-8 art:text-sm" value={query} onChange={(event) => setQuery(event.target.value)} onFocus={() => setSearchFocused(true)} onBlur={() => setSearchFocused(false)}/>
                  {query ? (<span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:size-10 art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4">
                      <PressButton type="button" className="art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:right-2 art:top-2 art:flex art:size-6 art:items-center art:justify-center art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full" aria-label="Clear search" tabIndex={0} onClick={() => {
                setQuery("");
            }}>
                        <X className="art:size-3"/>
                      </PressButton>
                    </span>) : null}
                </div>
                <div className="art:contents"/>
              </div>
              <div className="art:flex art:rounded-full art:bg-muted/60 art:p-1">
                <PressButton className={layout === "grid" ? `${VIEW_BUTTON} art:bg-background art:text-foreground art:h-9 art:rounded-full` : VIEW_BUTTON_IDLE} aria-label="grid view" aria-pressed={layout === "grid"} onClick={() => setLayout("grid")}>
