export function ActionMenu({ label, actions, className, icon, }: {
    label: string;
    actions: readonly MenuAction[];
    className: string;
    icon: ReactNode;
}) {
    const reduce = useReducedMotion();
    const reactId = useId();
    const triggerId = `radix-${reactId}`;
    const contentId = `radix-${reactId}H1`;
    const triggerRef = useRef<HTMLButtonElement>(null);
    const highlight: HighlightValues = {
        x: useMotionValue(0), y: useMotionValue(0), width: useMotionValue(0),
        height: useMotionValue(0), opacity: useMotionValue(0),
    };
    const [open, setOpen] = useState(false);
    const openRef = useRef(false);
    useLayoutEffect(() => { openRef.current = open; }, [open]);
    const [present, setPresent] = useState(false);
    const [keyboardOpen, setKeyboardOpen] = useState(false);
    const [placement, setPlacement] = useState<Placement | null>(null);
    const [session, setSession] = useState(0);
    const openMenu = (viaKeyboard: boolean) => {
        if (!present)
            setSession((count) => count + 1);
        setKeyboardOpen(viaKeyboard);
        setOpen(true);
        setPresent(true);
    };
    const onClose = useCallback((byPointer: boolean) => {
        if (byPointer)
            triggerRef.current?.setAttribute("data-artemis-pointer-focus", "");
        setOpen(false);
    }, []);
    const onExited = useCallback(() => {
        setPresent(false);
        setPlacement(null);
        window.setTimeout(() => { if (!openRef.current)
            triggerRef.current?.focus(); }, 0);
    }, []);
    const clearPointerFocus = () => triggerRef.current?.removeAttribute("data-artemis-pointer-focus");
    return (<>
      <motion.button ref={triggerRef} type="button" tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} id={triggerId} aria-haspopup="menu" aria-expanded={open} data-state={open ? "open" : "closed"} className={className} aria-label={label} aria-controls={open ? contentId : undefined} data-radix-popper-side={present && placement ? placement.side : undefined} data-radix-popper-align={present && placement ? "end" : undefined} onPointerDown={(event) => {
            if (event.button !== 0 || event.ctrlKey)
                return;
            if (open) {
                onClose(false);
            }
            else {
                event.preventDefault();
                openMenu(false);
            }
        }} onKeyDown={(event) => {
            clearPointerFocus();
            if (event.key === "Enter" || event.key === " ") {
                if (open)
                    onClose(false);
                else
                    openMenu(true);
            }
            else if (event.key === "ArrowDown") {
                openMenu(true);
            }
            if (event.key === "Enter" || event.key === " " || event.key === "ArrowDown")
                event.preventDefault();
        }} onBlur={clearPointerFocus}>
        {icon}
      </motion.button>
      {present && triggerRef.current
            ? artemisCreatePortal(<MenuContent highlight={highlight} key={session} open={open} triggerId={triggerId} contentId={contentId} trigger={triggerRef.current} actions={actions} keyboardOpen={keyboardOpen} onPlacement={setPlacement} onClose={onClose} onExited={onExited}/>, document.body)
            : null}
    </>);
}

