export function byteLength(text: string) {
    return new TextEncoder().encode(text).length;
}
function seedFile(id: string, name: string, parentId: string | null, content: string, modified: number, starred = false): Entry {
    return { id, kind: "file", name, parentId, starred, modified, content, size: byteLength(content) };
}
export function seedEntries(): Entry[] {
