        seedFile("guidelines", "Writing guidelines.md", "design", GUIDELINES, 6),
        seedFile("getting-started", "Getting started.md", "documents", GETTING_STARTED, 7),
        seedFile("checklist", "Launch checklist.txt", "projects", CHECKLIST, 5),
    ];
