export function formatSize(bytes: number) {
    if (bytes < 1024)
        return `${bytes} B`;
    if (bytes < 1024 * 1024)
        return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}
export function itemCountLabel(count: number) {
    return `${count} ${count === 1 ? "item" : "items"}`;
}
export function previewText(entry: Entry) {
    return (entry.content ?? "").slice(0, 220);
}
export function sortEntries(entries: Entry[], sort: SortKey) {
    const copy = [...entries];
    if (sort === "modified")
        copy.sort((a, b) => b.modified - a.modified);
    else
        copy.sort((a, b) => a.name.localeCompare(b.name));
    return copy;
}
export function matchesQuery(entry: Entry, query: string) {
    const q = query.trim().toLowerCase();
    return !q || entry.name.toLowerCase().includes(q);
}
export function descendants(entries: Entry[], folderId: string): Entry[] {
    const out: Entry[] = [];
    const walk = (parentId: string) => {
        for (const e of entries) {
            if (e.parentId !== parentId)
                continue;
            out.push(e);
            if (e.kind === "folder")
                walk(e.id);
        }
    };
    walk(folderId);
    return out;
}
export function folderChain(entries: Entry[], folderId: string | null): Entry[] {
    const chain: Entry[] = [];
    let id = folderId;
    while (id) {
        const folder = entries.find((e) => e.id === id && e.kind === "folder");
        if (!folder)
            break;
        chain.unshift(folder);
        id = folder.parentId;
    }
    return chain;
}
export const NAME_ERROR = "Enter a name without slashes or control characters.";
export const DUPLICATE_ERROR = "There\u2019s already an item with that name here.";
export function validateName(entries: Entry[], raw: string, parentId: string | null, selfId?: string): string | null {
    const name = raw.trim();
    if (!name || /[/\\\u0000-\u001f\u007f]/.test(name))
        return NAME_ERROR;
    const lower = name.toLowerCase();
    if (entries.some((e) => e.parentId === parentId && e.id !== selfId && e.name.toLowerCase() === lower))
        return DUPLICATE_ERROR;
    return null;
}
export function uniqueName(taken: Set<string>, name: string) {
    if (!taken.has(name.toLowerCase()))
        return name;
    const dot = name.lastIndexOf(".");
    const base = dot > 0 ? name.slice(0, dot) : name;
    const ext = dot > 0 ? name.slice(dot) : "";
    let n = 2;
    while (taken.has(`${base} (${n})${ext}`.toLowerCase()))
        n += 1;
    return `${base} (${n})${ext}`;
}
export function isTextFile(name: string, mime: string) {
    return mime.startsWith("text/") || /\.(md|txt|csv|json|tsv|log)$/i.test(name);
}
export function fileIconKind(entry: Entry): "spreadsheet" | "text" | "image" | "file" {
    if (/\.(csv|tsv|xlsx?)$/i.test(entry.name))
        return "spreadsheet";
    if (entry.mime?.startsWith("image/"))
        return "image";
    if (entry.content !== undefined)
        return "text";
    return "file";
}

