import {useRef,useState,type DragEvent} from "react";
export function useArtemisFileDrag(){
 const entered=useRef(new Set<EventTarget>()),[dragging,setDragging]=useState(false);
 const reset=()=>{entered.current.clear();setDragging(false)};
 const accepts=(event:DragEvent)=>Array.from(event.dataTransfer.types).some(t=>t==="Files");
 return {dragging,reset,events:{
  onDragEnter(event:DragEvent){if(!accepts(event))return;event.preventDefault();entered.current.add(event.target);setDragging(true)},
  onDragLeave(event:DragEvent){entered.current.delete(event.target);if(!entered.current.size)setDragging(false)},
  onDragOver(event:DragEvent){if(accepts(event))event.preventDefault()}
 }};
}
